## The three scope types

```js
var globalVar = 'I am global';

function outer() {
  var funcVar = 'function scoped'; // only accessible inside outer()

  if (true) {
    let blockVar   = 'block scoped';  // only accessible in this {}
    const alsoBlock = 'also block';   // same
    var notBlock   = 'still function'; // hoisted to function scope!
  }

  console.log(funcVar);    // ✅
  console.log(notBlock);   // ✅  (var leaks out of the block)
  // console.log(blockVar); // ❌ ReferenceError
}
```

## Scope chain lookup

```js
const x = 'global';

function outer() {
  const x = 'outer';
  function inner() {
    // x not declared here — walks up the chain:
    console.log(x); // 'outer' (found in outer's scope)
  }
  inner();
}
```

## Closures capture scope

```js
function makeCounter() {
  let count = 0;            // captured in closure
  return () => ++count;     // inner fn holds reference to count
}

const inc = makeCounter();
inc(); // 1
inc(); // 2  — count persists between calls
```

## Module scope

ES modules each have their own module scope — `import`/`export` cross module boundaries explicitly. Nothing bleeds into global scope.

## Where each comes from

```js
// undefined — the language provides it
let x;              // x === undefined
function f(a) { return a; }
f();                // undefined (argument not passed)
const obj = {};
obj.missing;        // undefined (property not set)

// null — the programmer provides it
const user = fetchUser(); // might return null if not found
const el   = document.querySelector('.missing'); // null
```

## Checking

```js
// Specific checks:
x === undefined   // true only for undefined
x === null        // true only for null

// Combined check (most common):
x == null         // true for BOTH null and undefined

// Type check (safe even if x is undeclared):
typeof x === 'undefined'
```

## Optional chaining handles both

```js
const city = user?.address?.city;
// undefined if user is null/undefined, or address is null/undefined
```

## Nullish coalescing

```js
const name = user?.name ?? 'Anonymous';
// ?? returns right side only for null or undefined (unlike || which also catches '')
```

## Block scoping

```js
function example() {
  var x = 'function scoped';
  let y = 'block scoped';

  if (true) {
    var x = 'still same x'; // overwrites outer x!
    let y = 'different y';  // new binding, only in this block
    console.log(y); // 'different y'
  }

  console.log(x); // 'still same x' — var leaked out
  console.log(y); // 'block scoped'  — let did not
}
```

## Temporal Dead Zone

```js
console.log(a); // undefined — var is hoisted and initialised
console.log(b); // ReferenceError — let is in TDZ
var a = 1;
let b = 2;
```

## No re-declaration

```js
var v = 1;
var v = 2; // fine with var

let l = 1;
let l = 2; // SyntaxError: Identifier 'l' has already been declared
```

## let vs const

```js
let count = 0;
count++;          // ✅ let can be reassigned

const MAX = 100;
MAX = 200;        // ❌ TypeError: Assignment to constant variable

const obj = {};
obj.x = 1;        // ✅ const prevents rebinding, not mutation
```

## undefined — declared, no value

```js
let x;
console.log(x);          // undefined — no error
console.log(typeof x);   // 'undefined'
console.log(x === undefined); // true
```

## Not defined — no declaration at all

```js
console.log(y);        // ReferenceError: y is not defined
console.log(typeof y); // 'undefined' — typeof is safe!
```

## Practical safe check

```js
// When you don't know if the variable was declared:
if (typeof myLib !== 'undefined') {
  myLib.init();
}

// Or use optional chaining on globalThis:
globalThis.myLib?.init();
```

## Function parameters

```js
function greet(name) {
  // name is declared (parameter), but undefined if not passed
  console.log(name);         // undefined
  console.log(name === undefined); // true
}
greet(); // called without argument
```

## Object properties

```js
const obj = { a: 1 };
console.log(obj.b); // undefined — property not set, not an error
```
